with fun non_english_count($m: movie) -> integer:
  match $m has languages $l; $l != "English";
  return count;

with fun language_count($m: movie) -> integer:
  match $m has languages $l;
  return count;

match
$m isa movie;
let $ne = non_english_count($m);
let $total = language_count($m);
$total > 0;
let $half = $total / 2;
$ne > $half;
limit 3;
fetch { "title": $m.title };

