with fun user_country_count($m: movie) -> integer:
  match
  $r isa rated (film: $m, user: $u);
  located_in (resident: $u, country: $c);
  select $c;
  distinct;
  return count;

match
$m isa movie;
let $cc = user_country_count($m);
$cc > 10;
limit 5;
fetch { "title": $m.title, "countries": $cc };

